{
  "mechanisms": [
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A bonus added to the stage-1 value of the action chosen on the previous trial.",
      "params": [
        {
          "name": "perseveration",
          "bounds": [
            0,
            5
          ]
        }
      ],
      "evidence": "q_stage1_eff = q_stage1.copy()\nif prev_action_1 != -1:\n    q_stage1_eff[prev_action_1] += perseveration",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Unchosen stage-2 action values decay towards zero on each trial.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_a2 = 1 - action_2[trial]\nq_stage2[state_idx, unchosen_a2] *= (1 - decay)\n\nunchosen_state = 1 - state_idx\nq_stage2[unchosen_state, :] *= (1 - decay)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage-1 values are updated using a combination of the stage-1 prediction error and the stage-2 prediction error weighted by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_param",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "combined_delta = delta_stage1 + lambda_param * delta_stage2\nq_stage1[action_1[trial]] += lr * combined_delta",
      "expressible_in_slots": true
    }
  ]
}
